// Generates seed/staging-seed.sql with FAKE data for local dev and the staging database.
// NEVER run the generated file against production.
import { writeFileSync, mkdirSync } from 'node:fs';
import { hashPassword } from '../src/lib/password.js';
import { BARANGAYS } from '../src/lib/constants.js';
import { normName, lastPeriods, todayPH } from '../src/lib/util.js';

let seed = 20261104;
const rnd = (n) => { seed = (seed * 1664525 + 1013904223) % 4294967296; return Math.floor((seed / 4294967296) * n); };
const q = (s) => `'${String(s).replace(/'/g, "''")}'`;

const ADMIN_PW = 'Staging-Admin-2026!';
const STAFF_PW = 'Staging-Treasurer-2026!';
const adminHash = await hashPassword(ADMIN_PW);
const staffHash = await hashPassword(STAFF_PW);

const FIRST = ['Maria', 'Jose', 'Ana', 'Juan', 'Rosa', 'Pedro', 'Luz', 'Carlo', 'Elena', 'Ramon', 'Gina', 'Noel', 'Liza', 'Dante', 'Cora'];
const LAST = ['Dela Cruz', 'Santos', 'Reyes', 'Fabro', 'Mendoza', 'Ramos', 'Garcia', 'Fruelda', 'Aguilar', 'Soriano', 'Villanueva', 'Fetalvero'];
const SITIO = ['Centro', 'Riverside', 'Kanluran', 'Silangan', 'Looban', 'Baybay'];

const sql = [];
sql.push('-- FAKE DATA for staging/local only. Generated by scripts/make-seed.mjs');
const label = (b) => b.replace(/(^|-)(\w)/g, (m, a, c) => a + c.toUpperCase());

// users: 1 = admin, then a treasurer + a backup staff per barangay
sql.push(`INSERT INTO admin_users (user_id, username, password_hash, full_name, role, barangay) VALUES (1, 'admin', ${q(adminHash)}, 'Staging Administrator', 'admin', NULL);`);
const creators = {};
BARANGAYS.forEach((b, i) => {
  const t = 2 + i * 2, s = t + 1;
  creators[b] = [t, s];
  sql.push(`INSERT INTO admin_users (user_id, username, password_hash, full_name, role, barangay) VALUES (${t}, ${q('treasurer_' + b.replace('-', ''))}, ${q(staffHash)}, ${q('Treasurer of ' + label(b))}, 'treasurer', ${q(b)});`);
  sql.push(`INSERT INTO admin_users (user_id, username, password_hash, full_name, role, barangay) VALUES (${s}, ${q('staff_' + b.replace('-', ''))}, ${q(staffHash)}, ${q('Backup staff of ' + label(b))}, 'staff', ${q(b)});`);
});

// customers: 6 per barangay
const customers = [];
let meter = 1000;
for (const b of BARANGAYS) {
  for (let i = 0; i < 6; i++) {
    meter++;
    const c = { meter, first: FIRST[rnd(FIRST.length)], last: LAST[rnd(LAST.length)], barangay: b, sitio: SITIO[rnd(SITIO.length)], reading: 100 + rnd(400) };
    customers.push(c);
    sql.push(`INSERT INTO customers (meter_id, first_name, last_name, first_name_norm, last_name_norm, barangay, sitio) VALUES (${c.meter}, ${q(c.first)}, ${q(c.last)}, ${q(normName(c.first))}, ${q(normName(c.last))}, ${q(c.barangay)}, ${q(c.sitio)});`);
  }
}

// bills for the last 4 months, payments for most of the older ones
const today = todayPH();
const periods = lastPeriods(4);
const nextDue = (p) => { let [y, m] = p.split('-').map(Number); m++; if (m === 13) { m = 1; y++; } return `${y}-${String(m).padStart(2, '0')}-10`; };
let billId = 0;
const payments = [];
for (const [pi, period] of periods.entries()) {
  for (const c of customers) {
    const use = 8 + rnd(25);
    const pre = c.reading, curr = pre + use;
    c.reading = curr;
    const amount = 60 + use * 20, surcharge = 0, due = nextDue(period);
    billId++;
    sql.push(`INSERT INTO bills (bill_id, meter_id, billing_period, pre_reading, curr_reading, tcmeter, amount, surcharge, bill_amount, duedate, posted_by) VALUES (${billId}, ${c.meter}, ${q(period)}, ${pre}, ${curr}, ${use}, ${amount}, ${surcharge}, ${amount + surcharge}, ${q(due)}, 1);`);
    const old = pi < periods.length - 1;
    const roll = rnd(100);
    if ((old && roll < 85) || (!old && roll < 35)) {
      let paid = amount; if (roll % 7 === 0) paid = Math.floor(amount / 2);
      let date = [...due.slice(0, 8), '05'].join('');
      if (date > today) date = today;
      payments.push({ date, billId, paid, by: creators[c.barangay][rnd(2)] });
    }
  }
}
payments.sort((a, b) => a.date.localeCompare(b.date) || a.billId - b.billId);
const counters = {};
payments.forEach((p) => {
  const y = p.date.slice(0, 4);
  counters[y] = (counters[y] || 0) + 1;
  sql.push(`INSERT INTO payments (receipt_no, bill_id, payment_date, amount_paid, created_by) VALUES (${q(`OR-${y}-${String(counters[y]).padStart(6, '0')}`)}, ${p.billId}, ${q(p.date)}, ${p.paid}, ${p.by});`);
});
for (const [y, n] of Object.entries(counters)) sql.push(`INSERT INTO receipt_counters (year, last_no) VALUES (${y}, ${n});`);

sql.push(`INSERT INTO complaints (first_name, last_name, barangay, meter_id, category, message, matched) VALUES ('Maria', 'Santos', 'ipil', 1019, 'leak', 'May tagas sa tubo malapit sa aming bahay simula pa kahapon.', 0);`);
sql.push(`INSERT INTO complaints (first_name, last_name, barangay, meter_id, category, message, matched, status) VALUES ('Juan', 'Reyes', 'silum', 1050, 'no_water', 'No water since Monday morning in our sitio.', 0, 'in_progress');`);

mkdirSync(new URL('../seed/', import.meta.url), { recursive: true });
writeFileSync(new URL('../seed/staging-seed.sql', import.meta.url), sql.join('\n') + '\n');
console.log(`Wrote seed/staging-seed.sql (${customers.length} customers, ${billId} bills, ${payments.length} payments)`);
console.log('FAKE logins -> admin / ' + ADMIN_PW);
console.log('               treasurer_<barangay> or staff_<barangay> / ' + STAFF_PW + '   e.g. treasurer_ipil');
